#include "usermodfx.h"
#include <stdint.h>
namespace{static constexpr float SR=48000.f;static float hL[8]={},hR[8]={},ph=0,ft=.15f,dt=0,f=.15f,d=0;static uint32_t pos=0;static inline float c01(float x){return x<0?0:(x>1?1:x);}static inline float ca(float x){return x<-1?-1:(x>1?1:x);}static inline float wr(float x){return x>=1?x-1:x;}static inline float hist(float*h,int back){return h[(pos+8u-(uint32_t)back)&7u];}static void reset(){for(int i=0;i<8;i++)hL[i]=hR[i]=0;pos=0;ph=0;}}
void MODFX_INIT(uint32_t p,uint32_t a){(void)p;(void)a;reset();}void MODFX_PROCESS(const float*x,float*y,const float*sx,float*sy,uint32_t n){(void)sx;(void)sy;for(uint32_t i=0;i<n;i++){f+=(ft-f)*.0015f;d+=(dt-d)*.0015f;hL[pos]=x[2*i];hR[pos]=x[2*i+1];float realL=hist(hL,3),realR=hist(hR,3);float qL=-.2122066f*hist(hL,6)-.6366198f*hist(hL,4)+.6366198f*hist(hL,2)+.2122066f*hist(hL,0);float qR=-.2122066f*hist(hR,6)-.6366198f*hist(hR,4)+.6366198f*hist(hR,2)+.2122066f*hist(hR,0);float hz=.2f+4800.f*f*f;ph=wr(ph+hz/SR);float c=fx_cosf(ph),s=fx_sinf(ph);float upL=realL*c-qL*s;float upR=realR*c-qR*s;float dnR=realR*c+qR*s;float wetR=upR+(dnR-upR)*d;float mix=d;y[2*i]=ca(realL*(1-mix)+upL*mix);y[2*i+1]=ca(realR*(1-mix)+wetR*mix);pos=(pos+1u)&7u;}}
void MODFX_SUSPEND(){reset();}void MODFX_RESUME(){reset();}void MODFX_PARAM(uint8_t i,int32_t v){float n=c01(q31_to_f32(v));if(i==k_user_modfx_param_time)ft=n;else if(i==k_user_modfx_param_depth)dt=n;}
